Here’s the ready‑to‑paste HTML snippet that embeds the map you requested, shows the **State Library** marker, and draws three circles at the coordinates you supplied.

```html
<!-- Embedded Google Map (centered on the State Library) -->
<iframe
    width="600"
    height="400"
    style="border:0"
    loading="lazy"
    allowfullscreen
    src="https://www.google.com/maps/embed/v1/view?key=YOUR_API_KEY
        &center=34.052235,-118.243683
        &zoom=15
        &maptype=roadmap">
</iframe>

<script>
  // This script uses the Google Maps JavaScript API to add the marker
  // and the three circles after the map loads.
  function initMap() {
    const map = new google.maps.Map(document.querySelector('iframe').contentWindow.document.body, {
      center: { lat: 34.052235, lng: -118.243683 },
      zoom: 15,
      mapTypeId: 'roadmap'
    });

    // State Library marker
    new google.maps.Marker({
      position: { lat: 34.052235, lng: -118.243683 },
      map,
      title: 'State Library'
    });

    // Circle style (you can adjust radius, colors, etc.)
    const circleOptions = {
      map,
      radius: 100,               // metres
      strokeColor: '#FF0000',
      strokeOpacity: 0.8,
      strokeWeight: 2,
      fillColor: '#FF0000',
      fillOpacity: 0.35
    };

    // First circle
    new google.maps.Circle({
      ...circleOptions,
      center: { lat: 34.052235, lng: -118.243683 }
    });

    // Second circle
    new google.maps.Circle({
      ...circleOptions,
      center: { lat: 34.053690, lng: -118.2423732 }
    });

    // Third circle
    new google.maps.Circle({
      ...circleOptions,
      center: { lat: 34.05381, lng: -118.242751 }
    });
  }

  // Load the Maps JavaScript API and call initMap when ready
  const script = document.createElement('script');
  script.src = `https://maps.googleapis.com/maps/api/js?key=YOUR_API_KEY&callback=initMap`;
  script.async = true;
  script.defer = true;
  document.head.appendChild(script);
</script>
```

