## 📄 Full HTML (copy‑and‑paste)

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Form with 300 wpm Typing Animation</title>
<style>
  body {font-family: sans-serif; max-width: 500px; margin: 2rem auto;}
  .form-field {position: relative; margin-bottom: 1.5rem;}
  .typing-placeholder {position: absolute; left: 0.75rem; top: 0.5rem; pointer-events: none;}
  input, textarea {width: 100%; padding: 0.75rem; font-size: 1rem;}
  button {padding: 0.75rem 1.5rem; font-size: 1rem; cursor: pointer;}
</style>
</head>
<body>

<form id="demoForm">
  <div class="form-field">
    <svg id="namePlaceholder" class="typing-placeholder"></svg>
    <input type="text" id="name" autocomplete="off">
  </div>

  <div class="form-field">
    <svg id="emailPlaceholder" class="typing-placeholder"></svg>
    <input type="email" id="email" autocomplete="off">
  </div>

  <button type="submit" id="submitBtn">Submit</button>
</form>

<script type="module">
  // -------------------------------------------------
  // 1️⃣  Import the typing‑animation utilities
  // -------------------------------------------------
  import {
    createTypingSVG,
    setTypingAnimation,
    customizeCursorStyle,
    animateTextFormatting
  } from './typing-utils.js';   // ← adjust the path to where your library lives

  // -------------------------------------------------
  // 2️⃣  Helper to initialise a placeholder SVG
  // -------------------------------------------------
  function initPlaceholder(svgId, text, opts = {}) {
    const svg = createTypingSVG({
      text,
      fontFamily: opts.fontFamily || 'sans-serif',
      fontSize: opts.fontSize || 14,
      fontColor: opts.fontColor || '#777',
      // ---- 300 wpm ----
      typingSpeed: 300
    });
    document.getElementById(svgId).innerHTML = svg;

    // No explicit delay → library uses its default (≈ 1 s)
    setTypingAnimation({
      svgId,
      // ---- 300 wpm ----
      typingSpeed: 300
    });

    customizeCursorStyle({
      cursorShape: 'verticalBar',
      cursorColor: opts.cursorColor || '#777'
    });

    if (opts.fontStyle) {
      animateTextFormatting({
        fontStyle: opts.fontStyle,
        textColor: opts.textColor
      });
    }
  }

  // -------------------------------------------------
  // 3️⃣  Initialise placeholders (speed = 300 wpm)
  // -------------------------------------------------
  initPlaceholder('namePlaceholder', 'Your full name', {
    cursorColor: '#555',
    fontStyle: 'italic'
  });
  initPlaceholder('emailPlaceholder', 'you@example.com', {
    cursorColor: '#555',
    fontStyle: 'italic'
  });

  // -------------------------------------------------
  // 4️⃣  Live preview (optional – still 300 wpm)
  // -------------------------------------------------
  function bindLivePreview(inputId, previewSvgId) {
    const input = document.getElementById(inputId);
    const previewSvg = document.getElementById(previewSvgId);
    previewSvg.innerHTML = `<text x="0" y="14" font-family="sans-serif" font-size="14" fill="#999"></text>`;
    const txt = previewSvg.querySelector('text');

    // 300 wpm ≈ 5 chars/sec → 200 ms per character
    const charDelay = 200;

    let timer = null;
    input.addEventListener('input', () => {
      clearTimeout(timer);
      const full = input.value;
      txt.textContent = '';
      let i = 0;
      function type() {
        if (i < full.length) {
          txt.textContent += full[i++];
          timer = setTimeout(type, charDelay);
        }
      }
      type();
    });
  }

  // Demo preview for the email field
  document.getElementById('email')
    .insertAdjacentHTML('afterend',
      '<svg id="emailPreview" class="typing-placeholder" style="margin-top:4px;"></svg>');
  bindLivePreview('email', 'emailPreview');

  // -------------------------------------------------
  // 5️⃣  Submit‑button animation (300 wpm)
  // -------------------------------------------------
  document.getElementById('demoForm').addEventListener('submit', e => {
    e.preventDefault();
    const btn = document.getElementById('submitBtn');
    btn.innerHTML = '<svg id="btnTyping"></svg>';

    const thankYou = createTypingSVG({
      text: 'Thank you!',
      fontFamily: 'sans-serif',
      fontSize: 16,
      fontColor: '#fff',
      typingSpeed: 300          // 300 wpm
    });
    document.getElementById('btnTyping').innerHTML = thankYou;

    setTypingAnimation({
      svgId: 'btnTyping',
      typingSpeed: 300          // 300 wpm
    });
    customizeCursorStyle({cursorShape: 'verticalBar', cursorColor: '#fff'});
    btn.style.background = '#28a745';
  });
</script>
</body>
</html>
```

### What changed?

| Location | Change |
|----------|--------|
| `createTypingSVG` (placeholders & button) | `typingSpeed: 300` |
| `setTypingAnimation` (placeholders & button) | `typingSpeed: 300` |
| `delayBeforeStart` | **Removed** – the function now uses its default delay (1 second). |
| Live‑preview typing delay | Adjusted to `200 ms` per character, which matches ~300 wpm. |

---

## 🎯 Quick checklist for your production code

1. **Set `typingSpeed: 300`** wherever you call `createTypingSVG` or `setTypingAnimation`.  
2. **Do not pass `delayBeforeStart`** (or set it to `undefined`) – the library will fall back to its built‑in default.  
3. If you need a *different* default delay for a specific field, just add `delayBeforeStart: <ms>` in the `setTypingAnimation` call.  

That’s it! Your form now types at **300 words‑per‑minute** with the default start‑delay, giving users a snappy, modern feel. 🚀
